sys_script_include.script:
var TraceFileAjax = Class.create();
TraceFileAjax.prototype = Object.extendsObject(AbstractAjaxProcessor, {

  linkFile: function() {
    var fileId = this.getParameter('sysparm_file_id');
    var storyId = this.getParameter('sysparm_story');
    var defectId = this.getParameter('sysparm_defect');

    if (!fileId)
      return "Invalid file reference.";

    var fileGR = new GlideRecord('sys_metadata');
    if (!fileGR.get(fileId))
      return "File not found.";

    var trace = new GlideRecord('u_trace_file');
    trace.initialize();
    trace.setValue('file_name', fileGR.getValue('name'));
    trace.setValue('file_sys_id', fileId);
    trace.setValue('file_type', fileGR.getRecordClassName());
    trace.setValue('created_by', gs.getUserID());

    var valid = false;

    if (storyId) {
      var story = new GlideRecord('rm_story');
      story.addQuery('number', storyId);
      story.query();
      if (story.next()) {
        trace.setValue('story', story.sys_id);
        valid = true;
      } else {
        return "Invalid Story ID: " + storyId;
      }
    }

    if (defectId) {
      var defect = new GlideRecord('rm_defect');
      defect.addQuery('number', defectId);
      defect.query();
      if (defect.next()) {
        trace.setValue('defect', defect.sys_id);
        valid = true;
      } else {
        return "Invalid Defect ID: " + defectId;
      }
    }

    if (valid) {
      trace.insert();
      return "Trace record created successfully.";
    } else {
      return "Trace not created. Please enter a valid Story or Defect ID.";
    }
  }

});
